import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Interactive, Sequence, interpolate, random, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Each diagonal of the grid rising, front row first. Frames on the 30 fps
// scene timeline, after `speed`. The ids are public: a saved `timing` prop
// refers to them.

type IsometricBuildElementId = `row:${number}`;

interface IsometricBuildTimingProps {
  grid?: number;
  stagger?: number;
}

const GRID = 5;
const STAGGER = 2;
/** The springs settle in about this long. */
const RISE = 24;

/** Tiles per side, as the component rounds `grid`. */
function tilesOf(grid: number) {
  return Math.max(1, Math.round(grid));
}

// `row:<k>` is the `k`-th diagonal to rise, counted from the front; the
// rows are a chain. Each block in a row rises at a seeded share of the
// row's `stagger` beat after the row starts.
const isometricBuildTimeline = defineTimeline<
  IsometricBuildElementId,
  IsometricBuildTimingProps
>(({ grid = GRID, stagger = STAGGER }) => {
  const n = tilesOf(grid);
  const rows = 2 * (n - 1) + 1;
  const elements: TimelineElement<IsometricBuildElementId>[] = [];
  for (let k = 0; k < rows; k++) {
    elements.push({
      id: `row:${k}`,
      lane: "Rows",
      label: `Row ${k + 1}`,
      start: k * stagger,
      length: k < rows - 1 ? stagger : stagger + RISE,
      follows: k > 0 ? `row:${k - 1}` : undefined,
      beats: { stagger },
    });
  }
  return elements;
});

type IsometricBuildProps = {
  /** Tiles per side. */
  grid?: number;
  /** Tallest regular block, in tile widths. The accent tower rises above it. */
  maxHeight?: number;
  /** Frames between consecutive diagonals rising. */
  stagger?: number;
  seed?: number;
  speed?: number;
  background?: string;
  /** Block color; side faces are this color shaded toward the background. */
  color?: string;
  /** The single accent tower. */
  accent?: string;
  /** Draw floor lines on the block faces. */
  floors?: boolean;
  /** Gap between neighbouring blocks, as a share of a tile. */
  gap?: number;
  /**
   * Moves, trims or stretches single rows of the build, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<IsometricBuildElementId>;
};

const isometricBuildDefaults: Required<
  Omit<IsometricBuildProps, "timing">
> = {
  grid: 5,
  maxHeight: 2.2,
  stagger: 2,
  seed: 4,
  speed: 1,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
  floors: true,
  gap: 0.04,
};

// True isometric: tile half-height = half-width · tan 30°, unit vertical edge
// matches the projected tile edge.
const ISO_Y = Math.tan(Math.PI / 6);
const ISO_Z = 1 / Math.cos(Math.PI / 6);
const FLOOR = 0.42;
const SHADE_LEFT = 0.32;
const SHADE_RIGHT = 0.6;

const fmt = (n: number) => Math.round(n * 10) / 10;

type Block = {
  i: number;
  j: number;
  height: number;
  accent: boolean;
  /** The diagonal it rises with, counted from the front. */
  row: number;
  /** Seeded share of the row's stagger it waits after the row starts. */
  jitter: number;
};

function makeBlocks(n: number, maxHeight: number, seed: number) {
  const r = (key: string) => random(`isometric-build-${seed}-${key}`);
  const inner = Math.max(1, n - 2);
  const ai = n > 2 ? 1 + Math.floor(r("ai") * inner) : 0;
  const aj = n > 2 ? 1 + Math.floor(r("aj") * inner) : 0;
  const blocks: Block[] = [];
  // Painter order: back (i + j small) to front.
  for (let sum = 0; sum <= 2 * (n - 1); sum++) {
    for (let i = 0; i < n; i++) {
      const j = sum - i;
      if (j < 0 || j >= n) continue;
      const accent = i === ai && j === aj;
      // One compact mass: heights follow a mound that peaks in the middle,
      // with a little seeded variation, snapped to whole floors so the
      // blocks stack like a single stepped sculpture rather than noise.
      const c = (n - 1) / 2;
      const centre = 1 - Math.hypot(i - c, j - c) / (Math.hypot(c, c) || 1);
      const raw =
        maxHeight *
        (0.2 + 0.8 * centre ** 1.3) *
        (0.75 + 0.5 * r(`h${i}-${j}`));
      const h = Math.max(FLOOR, Math.round(raw / FLOOR) * FLOOR);
      blocks.push({
        i,
        j,
        accent,
        height: accent ? maxHeight * 1.35 : h,
        // Front rows rise first.
        row: 2 * (n - 1) - sum,
        jitter: r(`d${i}-${j}`),
      });
    }
  }
  return blocks;
}

function IsometricBuildBase(props: IsometricBuildProps) {
  const {
    grid = isometricBuildDefaults.grid,
    maxHeight = isometricBuildDefaults.maxHeight,
    seed = isometricBuildDefaults.seed,
    speed = isometricBuildDefaults.speed,
    background = isometricBuildDefaults.background,
    color = isometricBuildDefaults.color,
    accent = isometricBuildDefaults.accent,
    floors = isometricBuildDefaults.floors,
    gap = isometricBuildDefaults.gap,
    timing,
  } = props;
  const inset = Math.min(0.45, Math.max(0, gap)) / 2;
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    isometricBuildTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const n = tilesOf(grid);
  const blocks = useMemo(
    () => makeBlocks(n, maxHeight, seed),
    [n, maxHeight, seed],
  );

  const tallest = maxHeight * 1.35;
  // Fit the diamond plus the tallest tower into the frame.
  const a = Math.min(
    (width * 0.64) / (2 * n),
    (height * 0.8) / (2 * n * ISO_Y + tallest * ISO_Z),
  );
  const b = a * ISO_Y;
  const hz = a * ISO_Z;
  const top = (height - (2 * n * b + tallest * hz)) / 2 + tallest * hz;
  const cx = width / 2;
  const P = (u: number, v: number, z: number) =>
    `${fmt(cx + (u - v) * a)} ${fmt(top + (u + v) * b - z * hz)}`;
  const poly = (...pts: string[]) => `M ${pts.join(" L ")} Z`;

  const unit = Math.min(width, height) / 720;
  const time = frame * speed;

  let ground = "";
  for (let k = 0; k <= n; k++) {
    ground += `M ${P(k, 0, 0)} L ${P(k, n, 0)} M ${P(0, k, 0)} L ${P(n, k, 0)} `;
  }

  return (
    <AbsoluteFill style={{ backgroundColor: background }}>
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Isometric city build"
        style={{ display: "block" }}
      >
        <path
          d={ground}
          fill="none"
          stroke={color}
          strokeOpacity={0.12}
          strokeWidth={unit}
        />
        {blocks.map((block) => {
          const row = tl.get(`row:${block.row}`);
          const s = spring({
            frame: time - (row.start + block.jitter * row.beat("stagger")),
            fps,
            config: { damping: 11, stiffness: 140, mass: 0.7 },
          });
          const opacity = interpolate(s, [0, 0.15], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          if (opacity <= 0) return null;
          const h = Math.max(0.02, block.height * s);
          const u0 = block.i + inset;
          const u1 = block.i + 1 - inset;
          const v0 = block.j + inset;
          const v1 = block.j + 1 - inset;
          const fill = block.accent ? accent : color;
          const left = poly(
            P(u0, v1, 0),
            P(u1, v1, 0),
            P(u1, v1, h),
            P(u0, v1, h),
          );
          const right = poly(
            P(u1, v0, 0),
            P(u1, v1, 0),
            P(u1, v1, h),
            P(u1, v0, h),
          );
          const roof = poly(
            P(u0, v0, h),
            P(u1, v0, h),
            P(u1, v1, h),
            P(u0, v1, h),
          );
          let lines = "";
          if (floors) {
            for (let z = FLOOR; z < h - FLOOR * 0.5; z += FLOOR) {
              lines += `M ${P(u0, v1, z)} L ${P(u1, v1, z)} L ${P(u1, v0, z)} `;
            }
          }
          return (
            <g key={`${block.i}-${block.j}`} opacity={opacity}>
              <path d={left} fill={fill} />
              <path d={left} fill={background} fillOpacity={SHADE_LEFT} />
              <path d={right} fill={fill} />
              <path d={right} fill={background} fillOpacity={SHADE_RIGHT} />
              {lines ? (
                <path
                  d={lines}
                  fill="none"
                  stroke={background}
                  strokeOpacity={0.35}
                  strokeWidth={unit * 1.2}
                />
              ) : null}
              <path
                d={roof}
                fill={fill}
                stroke={background}
                strokeOpacity={0.5}
                strokeWidth={unit}
                strokeLinejoin="round"
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  grid: {
    type: "number",
    default: 5,
    min: 2,
    max: 9,
    step: 1,
    description: "Tiles per side",
    hiddenFromList: false,
  },
  maxHeight: {
    type: "number",
    default: 2.2,
    min: 0.5,
    max: 4,
    step: 0.1,
    description: "Max height",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    default: 2,
    min: 0,
    max: 6,
    step: 0.5,
    description: "Stagger",
    hiddenFromList: false,
  },
  gap: {
    type: "number",
    default: 0.04,
    min: 0,
    max: 0.3,
    step: 0.01,
    description: "Gap",
    hiddenFromList: false,
  },
  floors: {
    type: "boolean",
    default: true,
    description: "Floor lines",
  },
  seed: {
    type: "number",
    default: 4,
    min: 1,
    max: 50,
    step: 1,
    description: "Seed",
    hiddenFromList: false,
  },
  background: {
    type: "color",
    default: "#111111",
    description: "Background",
  },
  color: {
    type: "color",
    default: "#FFFFFF",
    description: "Blocks",
  },
  accent: {
    type: "color",
    default: "#E5322D",
    description: "Accent tower",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["grid","maxHeight","stagger","gap","floors","seed","background","color","accent","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  grid: 5,
  maxHeight: 2.2,
  stagger: 2,
  gap: 0.04,
  floors: true,
  seed: 4,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
  speed: 1,
};

type IsometricBuildElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof IsometricBuildBase>;

const IsometricBuildInner = forwardRef<
  HTMLDivElement,
  IsometricBuildElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<IsometricBuild>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <IsometricBuildBase
          {...(componentProps as unknown as ComponentProps<typeof IsometricBuildBase>)}
        />
      </div>
    </Sequence>
  );
});

export const IsometricBuild = Interactive.withSchema({
  Component: IsometricBuildInner,
  componentName: "<IsometricBuild>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
